with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(DEALER_CODE), ''), '') as INTERMEDIARY_REFERENCE
        , MAIN_AGENT_SC_RATE as SERVICE_CHARGE_RATE
        , MAIN_AGENT_SC_AMT as SERVICE_CHARGE_AMOUNT
        , DEALER_CODE as DEALER_CODE
        , cast(null as varchar) as BROKERAGE_AMOUNT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(MAIN_AGENT_CODE), ''), '') as INTERMEDIARY_REFERENCE
        , MAIN_AGENT_SC_RATE as SERVICE_CHARGE_RATE
        , MAIN_AGENT_SC_AMT as SERVICE_CHARGE_AMOUNT
        , DEALER_CODE as DEALER_CODE
        , BROKERAGE_AMT as BROKERAGE_AMOUNT
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        INTERMEDIARY_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SERVICE_CHARGE_RATE end) as SERVICE_CHARGE_RATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SERVICE_CHARGE_AMOUNT end) as SERVICE_CHARGE_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then DEALER_CODE end) as DEALER_CODE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then BROKERAGE_AMOUNT end) as BROKERAGE_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, INTERMEDIARY_REFERENCE
),

hashed as (
    select
        *,
        case when INTERMEDIARY_REFERENCE is not null or SERVICE_CHARGE_RATE is not null or SERVICE_CHARGE_AMOUNT is not null or DEALER_CODE is not null or BROKERAGE_AMOUNT is not null
                     then md5(upper(coalesce(cast(INTERMEDIARY_REFERENCE as varchar), '') || '|' || coalesce(cast(SERVICE_CHARGE_RATE as varchar), '') || '|' || coalesce(cast(SERVICE_CHARGE_AMOUNT as varchar), '') || '|' || coalesce(cast(DEALER_CODE as varchar), '') || '|' || coalesce(cast(BROKERAGE_AMOUNT as varchar), '')))
                end as SAT_POLICY_INTERMEDIARY_SPLIT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_INTERMEDIARY_SPLIT_HASHDIFF is not null
